const content = $json.choices?.[0]?.message?.content || '';
let events = null;
try {
  const trimmed = String(content).trim();
  const fence = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fence ? fence[1].trim() : trimmed;
  const start = body.indexOf('{');
  const end = body.lastIndexOf('}');
  events = JSON.parse(body.substring(start, end + 1));
} catch (e) {
  events = null;
}
const keys = ['filings','order_book','promoter_activity','analyst_revisions','sector_strength','macro_beneficiaries','geopolitics','india_impact'];
const counts = {};
if (events) {
  keys.forEach(k => { counts[k] = Array.isArray(events[k]) ? events[k].length : 0; });
}
const eventsSummary = events
  ? keys.map(k => k + '=' + (counts[k] || 0)).join(', ')
  : 'parse_failed';
return [{ json: { events, eventsSummary, raw: content } }];

// Build context per config/pipeline-context-template.md
const dateIst = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
const runId = 'n8n-' + Date.now();
const watchlist = $env.WATCHLIST_SYMBOLS || 'RELIANCE,TCS,INFY';

const macroRows = $('Read Macro Dashboard').all().map(i => i.json);
const watchRows = $('Read Watchlist').all().map(i => i.json);
const filingRows = $('Read Filings').all().map(i => i.json).slice(-50);
const newsRows = $('Read News Flow').all().map(i => i.json).slice(-40);

let eventsSnippet = '(none — run Apps Script runNewsIntelligencePipeline or complete Section 14 node)';
try {
  const ev = $('Parse Events JSON').first().json;
  if (ev && ev.eventsSummary) eventsSnippet = ev.eventsSummary;
} catch (e) {}

const macroVerdict = macroRows.find(r => String(r.metric || r.Metric || '').includes('MACRO'))?.notes || macroRows.map(r => JSON.stringify(r)).join('\n');

const contextBlock = [
  '## RUN METADATA',
  'Date IST: ' + dateIst,
  'Run ID: ' + runId,
  'Watchlist: ' + watchlist,
  '',
  '## MACRO VERDICT',
  macroVerdict,
  '',
  '## WATCHLIST (Tab 11)',
  JSON.stringify(watchRows.slice(0, 15)),
  '',
  '## FILINGS (recent)',
  JSON.stringify(filingRows),
  '',
  '## NEWS (recent)',
  JSON.stringify(newsRows),
  '',
  '## EXTRACTED EVENTS (Section 14)',
  eventsSnippet,
  '',
  'Produce Top 10 JSON with conviction scores. See prompts/sections/04-stock-cards.md in repo.',
  '[USE REAL-TIME WEB SEARCH]'
].join('\n');

return [{ json: { dateIst, runId, watchlist, contextBlock } }];

